// use_figma script (read-only). Generated by `python3 scripts/figma-script.py tokens <mds-tag>` — do not edit by hand.
// Finds the library variables (by WEB code syntax) and text styles for the CSS a Magma component uses.
// A bare custom property name (`--magma-text-muted`) matches any code syntax that contains it.
// The CSS list covers <tag>.css and every file it @imports; LENGTHS are borders written as numbers.
/*__CONFIG__*/

const vars = await figma.variables.getLocalVariablesAsync();
const cols = await figma.variables.getLocalVariableCollectionsAsync();
const colName = (id) => (cols.find((c) => c.id === id) || {}).name;
const norm = (s) => s.replace(/\s+/g, '');
const out = {};
for (const css of CSS) {
  const exact = vars.filter(
    (v) => v.codeSyntax && v.codeSyntax.WEB && norm(v.codeSyntax.WEB) === norm(css),
  );
  const hits = exact.length
    ? exact
    : vars.filter(
        (v) =>
          v.codeSyntax &&
          v.codeSyntax.WEB &&
          v.codeSyntax.WEB.includes(css.replace(/^var\(|\)$/g, '')),
      );
  out[css] = hits.length
    ? hits
        .slice(0, 6)
        .map(
          (v) =>
            `${colName(v.variableCollectionId)} · ${v.name} · ${v.id} · WEB ${v.codeSyntax.WEB} · scopes ${v.scopes.join(',') || 'hidden'}`,
        )
    : /--(duration|ease)/.test(css)
      ? ['motion token: no Figma equivalent, leave it out']
      : /--shadow/.test(css)
        ? ['shadow: use an effect style (Shadow/*, Elevation/*), see conventions.md#tokens']
        : [
            'NOT FOUND — check the CSS, or create a "Figma only:" variable (see conventions.md#tokens)',
          ];
}
// borders/outlines the CSS writes as a number (1px): the FLOAT variables with that value
const resolve = (v) => {
  let val = Object.values(v.valuesByMode)[0];
  for (let i = 0; i < 10 && val && val.type === 'VARIABLE_ALIAS'; i++) {
    const a = vars.find((x) => x.id === val.id);
    val = a ? Object.values(a.valuesByMode)[0] : null;
  }
  return val;
};
const lengths = {};
for (const n of LENGTHS) {
  const hits = vars.filter(
    (v) => v.resolvedType === 'FLOAT' && /border|outline|stroke/i.test(v.name) && resolve(v) === n,
  );
  lengths[n + 'px'] = hits.length
    ? hits.map(
        (v) =>
          `${colName(v.variableCollectionId)} · ${v.name} · ${v.id} · WEB ${(v.codeSyntax || {}).WEB || '-'}`,
      )
    : ['NOT FOUND — no border/outline variable with this value'];
}
const MAP = {
  h1: 'Title/H1',
  h2: 'Title/H2',
  h3: 'Title/H3',
  h4: 'Title/H4',
  h5: 'Title/H5',
  h6: 'Title/H6',
  action: 'Title/Action',
  paragraph: 'Info/Paragraph',
  detail: 'Info/Detail',
  caption: 'Info/Caption',
  label: 'Info/Label',
  option: 'Info/Option',
  tip: 'Info/Tip',
  snippet: 'Code/Snippet',
  hack: 'Code/Hack',
};
const styles = await figma.getLocalTextStylesAsync();
const typo = {};
for (const t of TYPOGRAPHY) {
  const s = styles.find((x) => x.name === MAP[t]);
  typo[t] = s ? `${s.name} · ${s.id}` : `NOT FOUND (${MAP[t] || 'no mapping'})`;
}
return { variables: out, literalLengths: lengths, textStyles: typo };
